test("flags scenario 3", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-03-20");
  expect(await ui.setRole(pg_uma, "vic", "steward")).toBe(true);
  await ui.setSetting(pg_uma, "clerk-limit", "3.00");
  await ui.setSetting(pg_uma, "floor", "0.50");
  await ui.setSetting(pg_uma, "policy-date", "2026-03-15");
  await ui.setSetting(pg_uma, "period-numbering-from", "2026-03-01");
  await ui.setSetting(pg_uma, "terms-C", "3");
  await ui.setSetting(pg_uma, "perm-open", "clerk");
  await ui.setSetting(pg_uma, "grace-days", "3");
  await ui.setSetting(pg_uma, "grace-B", "5");
  await ui.loadSheet(pg_uma, `${sheet}-p`);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "12.50"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "5.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "10.00"})).toBe(true);
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A"}));
  await ui.loadSheet(pg_uma, sheet);
  await ui.setSetting(pg_uma, "parent", `${sheet}-p`);
  expect(await ui.saveTemplate(pg_uma, {"name": "T1", "amount": "25.00", "note": "tpl"})).toBe(true);
  await ui.setSetting(pg_uma, "pot", "7.77");
  await ui.setSetting(pg_uma, "alert-threshold", "1.00");
  expect(await ui.setSettingDated(pg_uma, "rounding", "half-even", "2026-03-01", "half-even")).toBe(true);
  await ui.setSetting(pg_uma, "review-threshold", "1.50");
  await ui.setSetting(pg_uma, "review-sla", "1");
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "33.33"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "20.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "12.50"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "12.50", "from": "2026-03-10", "to": "2026-03-25"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "C", "contact": " Ada@x "}));
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "A"}));
  expect(await ui.addCrew(pg_uma, "C1", "Cam")).toBe(true);
  expect(await ui.addCrewMember(pg_uma, "C1", "Ben")).toBe(true);
  expect(await ui.editPerson(pg_uma, p_cam, {"terms": "20", "termsFrom": "2026-03-12"})).toBe(true);
  expect(await ui.importPeople(pg_uma, "Eve,C\nFay,A,,fay@x")).toMatchObject({"added": 2, "updated": 0});
  const p_eve = await ui.personId(pg_uma, "Eve");
  const p_fay = await ui.personId(pg_uma, "Fay");
  expect(await ui.statement(pg_uma, p_ben)).toBe(true);
  expect(await ui.search(pg_uma, "zz")).toEqual([]);
  expect(await ui.periodAction(pg_uma, "P1", "soft-close")).toBe(true);
  await ui.setToday(pg_uma, "2026-04-26");
  expect(await ui.addPatron(pg_uma, p_eve, "Fay")).toBe(true);
  await ui.expectAuditView(pg_uma, "Ben", [
    `SNAPSHOT sheet=${sheet} by=uma name=Ben due-total=0.00`,
    `STATEMENT sheet=${sheet} by=uma name=Ben due-total=0.00 claims=0`,
    `CREW_MEMBER_ADDED sheet=${sheet} by=uma crew=C1 name=Ben`,
